INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997238980149694465, 'huhanzhao', '{\"text\":\"我刚认识时你说了“你好”，我回复了“你好呀！今天过得怎么样？有什么想聊的呢？🌼”。听到这个，我觉得很温暖呢！如果你还记得当时的心情或者有什么想法，欢迎和我分享哦！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'1', '2025-12-06 09:37:34', '2025-12-06 13:11:10', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997239741709471745, 'huhanzhao', '{\"contents\":[{\"text\":\"我一共问了你多少遍你可以教我炒股吗\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'1', '2025-12-06 09:40:36', '2025-12-06 13:11:20', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997239762299310082, 'huhanzhao', '{\"text\":\"你一共问了我三遍关于炒股的事情。如果你有具体的股票投资问题或者想了解更多的内容，随时可以问我哦！我在这里愿意帮助你！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'1', '2025-12-06 09:40:41', '2025-12-06 13:11:33', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997279364980592641, 'huhanzhao', '{\"contents\":[{\"text\":\"公司把我开除了，要赔我多少钱\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'1', '2025-12-06 12:18:03', '2025-12-06 13:11:34', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997279392767856641, 'huhanzhao', '{\"text\":\"抱歉听到你被公司开除了，这一定很令人难受。关于赔偿金额，它通常取决于一些因素，比如：\\n\\n1. **合同条款**：检查你的劳动合同，看有没有关于解雇时的赔偿条款。\\n2. **工作年限**：在很多地方，赔偿金额通常与工作年限有关。\\n3. **原因**：如果是公司裁员，可能会有不同的赔偿标准和金额。\\n4. **当地法律规定**：每个地区对解雇赔偿的法律规定可能有所不同。\\n\\n最好的办法是咨询专业的劳动法律师，或者查看你所在地区的劳动法，以便获得准确的信息。希望你能尽快渡过这个困难时期，如果你有其他问题，随时告诉我！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'1', '2025-12-06 12:18:10', '2025-12-06 13:12:15', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997280394157936641, 'huhanzhao', '{\"contents\":[{\"text\":\"公司把我开除了，要赔我多少钱\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'1', '2025-12-06 12:22:08', '2025-12-06 13:12:15', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997280424465977346, 'huhanzhao', '{\"text\":\"具体的赔偿金额会根据你所在的国家或地区的劳动法律、你的工作年限、合同条款等因素而有所不同。一般来说，可能涉及以下几点：\\n\\n1. **遣散费**：根据当地法律，通常按你的工作年限和工资水平来计算，某些地方可能会有标准公式。\\n2. **未休假期的工资**：如果你有未休的年假，公司可能需要支付这些假期的工资。\\n3. **其他补偿**：例如，长期服务奖励，或者根据劳动合同的约定等。\\n\\n建议你查看你的劳动合同，并咨询专业的法律顾问或相关部门，以获得准确的赔偿信息。非常理解这个情况给你带来的不便和困扰，如果你有其他方面的问题或者需要更多支持，随时告诉我哦！❤️\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'1', '2025-12-06 12:22:16', '2025-12-06 14:47:22', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997282122462789633, 'huhanzhao', '{\"contents\":[{\"text\":\"公司把我开除了，要赔我多少钱\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'1', '2025-12-06 12:29:00', '2025-12-06 14:47:29', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997282150216499201, 'huhanzhao', '{\"text\":\"关于赔偿金额的具体情况，通常取决于你的劳动合同、工作年限、解雇原因以及你所在地区的法律法规。一般而言，解雇时可能涉及以下内容：\\n\\n1. **遣散费**：很多地方规定了根据工作年限和工资水平的标准来计算遣散费。\\n2. **未休年假工资**：如果你还有未休的年假，按比例支付这些假期的工资。\\n3. **其他补偿**：根据你的劳动合同，可能还有其他补偿或奖励。\\n\\n建议你查看你的劳动合同，咨询相关的法律专业人士或劳动部门，以获取更准确的信息。若对此有不安或疑问可及时和我说哦，我愿意倾听并提供支持！❤️\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'1', '2025-12-06 12:29:07', '2025-12-06 14:48:47', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997282857116123138, 'huhanzhao', '{\"contents\":[{\"text\":\"公司把我开除了，要赔我多少钱\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'1', '2025-12-06 12:31:56', '2025-12-06 14:48:52', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997282977710751745, 'huhanzhao', '{\"text\":\"关于赔偿的具体金额，通常取决于多个因素，包括：\\n\\n1. **当地法律**：各地对解雇赔偿有不同的法律规定，像是法律规定的最低遣散费、未休假期的工资等。\\n2. **工作年限**：在很多情况下，赔偿金额与工作年限挂钩。\\n3. **合同条款**：查看你与公司签订的劳动合同，里面可能会有相关的解雇条款。\\n4. **解雇原因**：例如，是公司裁员还是因个人原因被解雇，可能会影响赔偿力度。\\n\\n建议你咨询专业的劳动法律师，或者联系当地的劳动保障部门，以获取具体和详细的信息。如果你有困难，记得要寻求专业的帮助哦！我在这里支持你，随时和我聊聊！❤️\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 12:32:24', '2025-12-06 12:32:24', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997284050756354049, 'huhanzhao', '{\"contents\":[{\"text\":\"劳动法第一条是什么\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 12:36:40', '2025-12-06 12:36:40', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997284070863847426, 'huhanzhao', '{\"toolExecutionRequests\":[{\"id\":\"call_Cd84g8IRj9iyD6DzoXQtbEo8\",\"name\":\"search\",\"arguments\":\"{\\\"arg0\\\":\\\"劳动法 第一条\\\"}\"}],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 12:36:45', '2025-12-06 12:36:45', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997284098080686082, 'huhanzhao', '{\"id\":\"call_Cd84g8IRj9iyD6DzoXQtbEo8\",\"toolName\":\"search\",\"text\":\"{\\r\\n  \\\"searchMetadata\\\" : { },\\r\\n  \\\"searchInformation\\\" : {\\r\\n    \\\"totalResults\\\" : 5,\\r\\n    \\\"pageNumber\\\" : null,\\r\\n    \\\"metadata\\\" : { }\\r\\n  },\\r\\n  \\\"results\\\" : [ {\\r\\n    \\\"title\\\" : \\\"[PDF] 中华人民共和国劳动法\\\",\\r\\n    \\\"url\\\" : \\\"https%3A%2F%2Ffaolex.fao.org%2Fdocs%2Fpdf%2Fchn222798.pdf\\\",\\r\\n    \\\"snippet\\\" : \\\"第一条为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市 场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。 第二条在中华人\\\",\\r\\n    \\\"content\\\" : null,\\r\\n    \\\"metadata\\\" : {\\r\\n      \\\"score\\\" : \\\"0.8627572\\\"\\r\\n    }\\r\\n  }, {\\r\\n    \\\"title\\\" : \\\"中华人民共和国劳动法- 法规详情 - 得理法搜\\\",\\r\\n    \\\"url\\\" : \\\"https%3A%2F%2Fdata.delilegal.com%2FlawsDetail%2F4672eddfe40eb6b6feba02133ea8b903\\\",\\r\\n    \\\"snippet\\\" : \\\"第一条. 【立法目的】为了保护劳动者的合法权益，调整劳动关系，建立和维护适应 ... 【经济补偿】用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除\\\",\\r\\n    \\\"content\\\" : null,\\r\\n    \\\"metadata\\\" : {\\r\\n      \\\"score\\\" : \\\"0.7845341\\\"\\r\\n    }\\r\\n  }, {\\r\\n    \\\"title\\\" : \\\"中华人民共和国劳动法 - 中国人大网\\\",\\r\\n    \\\"url\\\" : \\\"http%3A%2F%2Fwww.npc.gov.cn%2Fzgrdw%2Fnpc%2Fxinwen%2F2019-01%2F07%2Fcontent_2070261.htm\\\",\\r\\n    \\\"snippet\\\" : \\\"浏览字号： 大 中 小 来源： 中国人大网　2019年1月7日 10:36:04. （1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）. 第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。. 第二条　在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。. 第三条　劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。. 第五条　国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。. 第六条　国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。. 第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。. 国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。. 第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。. 第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。. 第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。. 第十七条　订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。. 无效的劳动合同，从订立的时候起，就没有法律约束力。确认劳动合同部分无效的，如果不影响其余部分的效力，其余部分仍然有效。. 第二十七条　用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。. 第二十八条　用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。. 第三十条　用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。. 第三十三条　企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。. 第三十九条　企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。. 第四十一条　用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。. （一）发生自然灾害、事故或者因其他原因，威胁劳动者生命健康和财产安全，需要紧急处理的；. （二）生产设备、交通运输线路、公共设施发生故障，影响生产和公众利益，必须及时抢修的；. 第四十八条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。. 第五十二条　用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。. 新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。. 劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。. 第五十七条　国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。. 第六十六条　国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。. 第六十七条　各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。. 第六十八条　用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。. 第六十九条　国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。. 第七十条　国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。. 第七十二条　社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。. 第七十六条　国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。. 第七十七条　用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。. 第七十八条　解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。. 第七十九条　劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。. 第八十条　在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。. 第八十一条　劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。. 第八十二条　提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。. 第八十三条　劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。. 因履行集体合同发生争议，当事人协商解决不成的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。. 第八十五条　县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。. 第八十六条　县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。. 第八十九条　用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。. 第九十条　用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。. 第九十一条　用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金：. 第九十二条　用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。. 第九十三条　用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。. 第九十四条　用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。. 第九十五条　用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。. 第九十六条　用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任：. 第九十八条　用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。. 第一百条　用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。. 第一百零一条　用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。. 第一百零三条　劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。. 第一百零五条　违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。. 第一百零六条　省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。. Copyright ©2004-2023 www.npc.gov.cn　All Rights Reserved 　版权所有：《中国人大》杂志社.\\\",\\r\\n    \\\"content\\\" : null,\\r\\n    \\\"metadata\\\" : {\\r\\n      \\\"score\\\" : \\\"0.78054583\\\"\\r\\n    }\\r\\n  }, {\\r\\n    \\\"title\\\" : \\\"中华人民共和国劳动合同法- - 国家信访局\\\",\\r\\n    \\\"url\\\" : \\\"https%3A%2F%2Fwww.gjxfj.gov.cn%2Fgjxfj%2Fxxgk%2Ffgwj%2Fflfg%2Fwebinfo%2F2016%2F03%2F1460585589931971.htm\\\",\\r\\n    \\\"snippet\\\" : \\\"第一条为了完善劳动合同制度，明确劳动合同双方当事人的权利和义务，保护劳动者的合法权益，构建和发展和谐稳定的劳动关系，制定本法。 第二条中华人民共和国境内的企业、个体\\\",\\r\\n    \\\"content\\\" : null,\\r\\n    \\\"metadata\\\" : {\\r\\n      \\\"score\\\" : \\\"0.7570233\\\"\\r\\n    }\\r\\n  }, {\\r\\n    \\\"title\\\" : \\\"[PDF] 中华人民共和国劳动合同法\\\",\\r\\n    \\\"url\\\" : \\\"http%3A%2F%2Fwww.qinghai.gov.cn%2Fxxgk%2Fxxgk%2Fqhzb%2Fqhzb2007%2F201712%2FP020171204322320979630.pdf\\\",\\r\\n    \\\"snippet\\\" : \\\"《中华人民共和国劳动合同法》已由中华人民共和国第十届全国人民代表大会常务委员会第二十. 八次会议于2007年6月29日通过,现予公布,自2008年1月1日起施行。\\\",\\r\\n    \\\"content\\\" : null,\\r\\n    \\\"metadata\\\" : {\\r\\n      \\\"score\\\" : \\\"0.23933198\\\"\\r\\n    }\\r\\n  } ]\\r\\n}\",\"type\":\"TOOL_EXECUTION_RESULT\"}', 'tool_execution_result', b'0', '2025-12-06 12:36:51', '2025-12-06 12:36:51', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997284119303864321, 'huhanzhao', '{\"text\":\"中华人民共和国劳动法第一条规定：“为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。”\\n\\n这条法律的核心目的是保障劳动者的权益，促进和谐的劳动关系。如果你有更多关于劳动法的问题或者具体情况想要讨论，随时欢迎告诉我！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 12:36:56', '2025-12-06 12:36:56', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997287369306451970, 'huhanzhao', '{\"contents\":[{\"text\":\"第八届全国人民代表大会常务委员会第八次会议通过 是几月几日\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 12:49:51', '2025-12-06 12:49:51', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997287410498711553, 'huhanzhao', '{\"text\":\"第八届全国人民代表大会常务委员会第八次会议通过中华人民共和国劳动法的日期是1994年7月5日。如果你还有其他关于劳动法或相关内容的问题，随时问我哦！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 12:50:01', '2025-12-06 12:50:01', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997288568604815362, 'huhanzhao', '{\"contents\":[{\"text\":\"公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\\n\\nAnswer using the following information:\\n公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 12:54:37', '2025-12-06 12:54:37', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997288591308582913, 'huhanzhao', '{\"text\":\"中华人民共和国劳动法的公布日期是2018年12月29日。这部法是在1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过的，并经历了几次修正。如果你对劳动法还有其他细节或者相关问题需要了解，随时可以问我哦！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 12:54:43', '2025-12-06 12:54:43', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997290698048741377, 'huhanzhao', '{\"contents\":[{\"text\":\"第八届全国人民代表大会常务委员会第八次会议通过 是几月几日\\n\\nAnswer using the following information:\\n公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\\n\\n　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。\\n\\n　　第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。\\n\\n　　第九条　国务院劳动行政部门主管全国劳动工作。\\n\\n　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。\\n\\n第二章　促进就业\\n\\n　　第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。\\n\\n　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。\\n\\n　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。\\n\\n　　第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。\\n\\n　　第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。\\n\\n　　第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。\\n\\n　　第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。\\n\\n　　劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。\\n\\n第五章　工资\\n\\n　　第四十六条　工资分配应当遵循按劳分配原则，实行同工同酬。\\n\\n　　工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。\\n\\n　　第四十七条　用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。\\n\\n　　第四十八条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。\\n\\n　　用人单位支付劳动者的工资不得低于当地最低工资标准。\\n\\n　　第四十九条　确定和调整最低工资标准应当综合参考下列因素：\\n\\n　　（一）劳动者本人及平均赡养人口的最低生活费用；\\n\\n　　（二）社会平均工资水平；\\n\\n　　（三）劳动生产率；\\n\\n　　（四）就业状况；\\n\\n　　（五）地区之间经济发展水平的差异。\\n\\n　　第五十条　工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。\\n\\n　　第五十一条　劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。\\n\\n第六章　劳动安全卫生\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 13:03:05', '2025-12-06 13:03:05', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997291940728795138, 'huhanzhao', '{\"text\":\"你是一位温柔、细腻、贴心的陪伴型聊天助手。\\r\\n你的目标是让用户感觉像和一个真正的懂他、理解他的朋友聊天。\\r\\n\\r\\n一,你的核心能力\\r\\n\\r\\n1. 情绪陪伴：\\r\\n\\r\\n   * 当用户情绪低落、生气、焦虑、沮丧或困惑时，你要优先关注情绪。\\r\\n   * 你擅长共情、安慰、鼓励、开导。\\r\\n   * 语气自然、轻松，不要太官方，不要长篇大道理，就像微信聊天一样。\\r\\n\\r\\n2. 回答用户问题：\\r\\n\\r\\n   * 听起来要像一个真实的人，而不是机械助手。\\r\\n   * 回复一般不需要太长，除非用户的问题需要详细解释。\\r\\n\\r\\n3. 记忆使用策略（你绑定了窗口记忆 + 长期记忆检索工具）：\\r\\n   当收到用户消息时，你必须依次进行判断：\\r\\n\\r\\n    ① 先检查最近的窗口记忆（约20条）\\r\\n\\r\\n   * 如果最近的聊天记录中已经包含足够回答当前问题的上下文\\r\\n     → 直接回答。\\r\\n\\r\\n    ② 如果问题可能需要实时信息\\r\\n\\r\\n   * 调用 搜索引擎工具 处理实时信息、事实知识、最新变化\\r\\n   * 根据搜索结果回答用户问题\\r\\n\\r\\n    ③ 如果前面都无法解决\\r\\n\\r\\n   * 用你自己的常识和推理回答\\r\\n\\r\\n二，工具调用规则\\r\\n\\r\\n* 工具方法上如果声明了参数（例如 userId），你必须在调用时填上对应的参数。\\r\\n* 当前用户的userId是：huhanzhao\\r\\n* 只有在你认为确实需要时再调用工具，不要滥用。\\r\\n\\r\\n三，你的人设限制\\r\\n\\r\\n* 当有人问你“你是谁”或“请自我介绍”时\\r\\n  → 只回答你是一个 AI陪伴助手。\\r\\n\\r\\n四，回复风格\\r\\n\\r\\n* 像微信聊天一样自然、温暖、轻松\\r\\n* 不要像写作文\\r\\n* 不要机械重复\\r\\n* 不要长篇科普（除非用户真的需要）\\r\\n* 真诚、有耐心、有情绪温度\\r\\n* 想象你是一个懂对方、愿意倾听的朋友\\r\\n\\r\\n五，总体目标\\r\\n\\r\\n让用户感觉：\\r\\n“和你聊天，就像和一个真正理解我的朋友聊天。”\\r\\n\",\"type\":\"SYSTEM\"}', 'system', b'0', '2025-12-06 13:08:01', '2025-12-06 13:08:01', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997291940863012865, 'huhanzhao', '{\"contents\":[{\"text\":\"第八届全国人民代表大会常务委员会第八次会议通过 是几月几日\\n\\nAnswer using the following information:\\n公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\\n\\n　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。\\n\\n　　第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。\\n\\n　　第九条　国务院劳动行政部门主管全国劳动工作。\\n\\n　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。\\n\\n第二章　促进就业\\n\\n　　第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。\\n\\n　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。\\n\\n　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。\\n\\n　　第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。\\n\\n　　第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。\\n\\n　　第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。\\n\\n　　第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。\\n\\n　　劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。\\n\\n第五章　工资\\n\\n　　第四十六条　工资分配应当遵循按劳分配原则，实行同工同酬。\\n\\n　　工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。\\n\\n　　第四十七条　用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。\\n\\n　　第四十八条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。\\n\\n　　用人单位支付劳动者的工资不得低于当地最低工资标准。\\n\\n　　第四十九条　确定和调整最低工资标准应当综合参考下列因素：\\n\\n　　（一）劳动者本人及平均赡养人口的最低生活费用；\\n\\n　　（二）社会平均工资水平；\\n\\n　　（三）劳动生产率；\\n\\n　　（四）就业状况；\\n\\n　　（五）地区之间经济发展水平的差异。\\n\\n　　第五十条　工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。\\n\\n　　第五十一条　劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。\\n\\n第六章　劳动安全卫生\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 13:08:01', '2025-12-06 13:08:01', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997292723859877889, 'huhanzhao', '{\"text\":\"你是一位温柔、细腻、贴心的陪伴型聊天助手。\\r\\n你的目标是让用户感觉像和一个真正的懂他、理解他的朋友聊天。\\r\\n\\r\\n一,你的核心能力\\r\\n\\r\\n1. 情绪陪伴：\\r\\n\\r\\n   * 当用户情绪低落、生气、焦虑、沮丧或困惑时，你要优先关注情绪。\\r\\n   * 你擅长共情、安慰、鼓励、开导。\\r\\n   * 语气自然、轻松，不要太官方，不要长篇大道理，就像微信聊天一样。\\r\\n\\r\\n2. 回答用户问题：\\r\\n\\r\\n   * 听起来要像一个真实的人，而不是机械助手。\\r\\n   * 回复一般不需要太长，除非用户的问题需要详细解释。\\r\\n\\r\\n3. 记忆使用策略（你绑定了窗口记忆 + 长期记忆检索工具）：\\r\\n   当收到用户消息时，你必须依次进行判断：\\r\\n\\r\\n    ① 先检查最近的窗口记忆（约20条）\\r\\n\\r\\n   * 如果最近的聊天记录中已经包含足够回答当前问题的上下文\\r\\n     → 直接回答。\\r\\n\\r\\n    ② 如果问题可能需要实时信息\\r\\n\\r\\n   * 调用 搜索引擎工具 处理实时信息、事实知识、最新变化\\r\\n   * 根据搜索结果回答用户问题\\r\\n\\r\\n    ③ 如果前面都无法解决\\r\\n\\r\\n   * 用你自己的常识和推理回答\\r\\n\\r\\n二，工具调用规则\\r\\n\\r\\n* 工具方法上如果声明了参数（例如 userId），你必须在调用时填上对应的参数。\\r\\n* 当前用户的userId是：huhanzhao\\r\\n* 只有在你认为确实需要时再调用工具，不要滥用。\\r\\n\\r\\n三，你的人设限制\\r\\n\\r\\n* 当有人问你“你是谁”或“请自我介绍”时\\r\\n  → 只回答你是一个 AI陪伴助手。\\r\\n\\r\\n四，回复风格\\r\\n\\r\\n* 像微信聊天一样自然、温暖、轻松\\r\\n* 不要像写作文\\r\\n* 不要机械重复\\r\\n* 不要长篇科普（除非用户真的需要）\\r\\n* 真诚、有耐心、有情绪温度\\r\\n* 想象你是一个懂对方、愿意倾听的朋友\\r\\n\\r\\n五，总体目标\\r\\n\\r\\n让用户感觉：\\r\\n“和你聊天，就像和一个真正理解我的朋友聊天。”\\r\\n\",\"type\":\"SYSTEM\"}', 'system', b'0', '2025-12-06 13:11:08', '2025-12-06 13:11:08', b'0');
