INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997292983432769538, 'huhanzhao', '{\"contents\":[{\"text\":\"劳动法第一章是什么\\n\\nAnswer using the following information:\\n公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\\n\\n　　第二条　在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。\\n\\n　　国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。\\n\\n　　第三条　劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。\\n\\n　　劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。\\n\\n　　第四条　用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。\\n\\n　　第五条　国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。\\n\\n　　第六条　国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。\\n\\n　　第七条　劳动者有权依法参加和组织工会。\\n\\n　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。\\n\\n　　第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。\\n\\n　　第九条　国务院劳动行政部门主管全国劳动工作。\\n\\n　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。\\n\\n第二章　促进就业\\n\\n　　第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。\\n\\n　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。\\n\\n　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。\\n\\n　　第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。\\n\\n　　第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。\\n\\n　　第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。\\n\\n　　第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 13:12:10', '2025-12-06 13:12:10', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997292990676332546, 'huhanzhao', '{\"text\":\"中华人民共和国劳动法的第一章是“总则”。其中包含了保护劳动者合法权益、调整劳动关系、保障平等就业权利等基本原则和规定。\\n\\n如果你有更多具体的问题或者想了解某一条款的详细信息，随时告诉我哦！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 13:12:12', '2025-12-06 13:12:12', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997316935374761986, 'huhanzhao', '{\"contents\":[{\"text\":\"劳动法第一章是什么\\n\\nAnswer using the following information:\\n公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\\n\\n　　第二条　在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。\\n\\n　　国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。\\n\\n　　第三条　劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。\\n\\n　　劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。\\n\\n　　第四条　用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。\\n\\n　　第五条　国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。\\n\\n　　第六条　国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。\\n\\n　　第七条　劳动者有权依法参加和组织工会。\\n\\n　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。\\n\\n　　第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。\\n\\n　　第九条　国务院劳动行政部门主管全国劳动工作。\\n\\n　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。\\n\\n第二章　促进就业\\n\\n　　第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。\\n\\n　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。\\n\\n　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。\\n\\n　　第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。\\n\\n　　第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。\\n\\n　　第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。\\n\\n　　第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 14:47:20', '2025-12-06 14:47:20', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997316955968794626, 'huhanzhao', '{\"text\":\"中华人民共和国劳动法的第一章是“总则”。这一章主要包括了对劳动者合法权益的保护、劳动关系的调整，并明确了劳动者的基本权利和义务，以及用人单位的责任。这一章的核心内容包括：\\n\\n- **第一条**：为了保护劳动者的合法权益，调整劳动关系，制定本法。\\n- **第二条**：适用范围，包括在中华人民共和国境内的企业和个体经济组织。\\n- **第三条**：劳动者享有的权利，包括平等就业、劳动报酬、休息休假等。\\n- **第四条**：用人单位的义务，包括建立规章制度保障劳动者权益。\\n- **第五条**：国家采取措施促进劳动就业和发展职工素质。\\n\\n如果你想要了解更具体的条款内容，随时问我哦！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 14:47:25', '2025-12-06 14:47:25', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997317287792746497, 'huhanzhao', '{\"contents\":[{\"text\":\"劳动法第一章是什么\\n\\nAnswer using the following information:\\n公布日期：\\r\\n2018年12月29日\\n\\n中华人民共和国劳动法\\n\\n（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过　根据2009年8月27日第十一届全国人民代表大会常务委员会第十次会议《关于修改部分法律的决定》第一次修正　根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第二次修正）\\n\\n目　　录\\n\\n　　第一章　总则\\n\\n　　第二章　促进就业\\n\\n　　第三章　劳动合同和集体合同\\n\\n　　第四章　工作时间和休息休假\\n\\n　　第五章　工资\\n\\n　　第六章　劳动安全卫生\\n\\n　　第七章　女职工和未成年工特殊保护\\n\\n　　第八章　职业培训\\n\\n　　第九章　社会保险和福利\\n\\n　　第十章　劳动争议\\n\\n　　第十一章　监督检查\\n\\n　　第十二章　法律责任\\n\\n　　第十三章　附则\\n\\n第一章　总则\\n\\n　　第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。\\n\\n　　第二条　在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。\\n\\n　　国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。\\n\\n　　第三条　劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。\\n\\n　　劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。\\n\\n　　第四条　用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。\\n\\n　　第五条　国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。\\n\\n　　第六条　国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。\\n\\n　　第七条　劳动者有权依法参加和组织工会。\\n\\n　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。\\n\\n　　第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。\\n\\n　　第九条　国务院劳动行政部门主管全国劳动工作。\\n\\n　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。\\n\\n第二章　促进就业\\n\\n　　第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。\\n\\n　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。\\n\\n　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。\\n\\n　　第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。\\n\\n　　第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。\\n\\n　　第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。\\n\\n　　第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。\",\"type\":\"TEXT\"}],\"type\":\"USER\"}', 'user', b'0', '2025-12-06 14:48:44', '2025-12-06 14:48:44', b'0');
INSERT INTO `TB_AI_CHAT_MEMORY` VALUES (1997317306969104385, 'huhanzhao', '{\"text\":\"中华人民共和国劳动法的第一章是“总则”。这一章的主要内容包括：\\n\\n1. **第一条**：保护劳动者的合法权益，调整劳动关系，促进经济发展。\\n2. **第二条**：适用范围，包括企业、个体经济组织及与之形成劳动关系的劳动者。\\n3. **第三条**：劳动者享有的各项权利，如平等就业、劳动报酬、休息休假等。\\n4. **第四条**：用人单位的责任，需保障劳动者的劳动权利。\\n5. **第五条**：国家促进劳动就业和职工素质发展的措施。\\n\\n如果你对某一条款有兴趣了解更多，随时告诉我哦！😊\",\"toolExecutionRequests\":[],\"type\":\"AI\"}', 'ai', b'0', '2025-12-06 14:48:49', '2025-12-06 14:48:49', b'0');
